python3 << 'EOF'
import xml.etree.ElementTree as ET

tree = ET.parse('/work/output/artifacts/skill-bpmn-message-catch/AwaitApprovalMessage/AwaitApprovalMessage.bpmn')
root = tree.getroot()

ns = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

errors = []

# 1. Root is <bpmn:definitions>
tag = root.tag
print(f"Root tag: {tag}")
if 'definitions' not in tag:
    errors.append("Root is not a definitions element")

# Check namespaces
attribs = root.attrib
print(f"Namespaces declared: uipath={'http://uipath.org/schema/bpmn' in attribs.values()}, bpmn={'http://www.omg.org/spec/BPMN/20100524/MODEL' in attribs.values()}")

# 2. Collect all declared IDs
all_ids = set()
for el in root.iter():
    eid = el.get('id')
    if eid:
        all_ids.add(eid)
print(f"All declared IDs: {sorted(all_ids)}")

# 3. Check BPMNDiagram
diagrams = root.findall('.//bpmndi:BPMNDiagram', ns)
print(f"BPMNDiagram count: {len(diagrams)}")
if len(diagrams) != 1:
    errors.append(f"Expected exactly 1 BPMNDiagram, found {len(diagrams)}")

shapes = root.findall('.//bpmndi:BPMNShape', ns)
edges = root.findall('.//bpmndi:BPMNEdge', ns)
shape_refs = {s.get('bpmnElement') for s in shapes}
edge_refs = {e.get('bpmnElement') for e in edges}
print(f"BPMNShapes: {sorted(shape_refs)}")
print(f"BPMNEdges: {sorted(edge_refs)}")

# Collect flow nodes
process = root.find('.//bpmn:process', ns)
flow_nodes = []
for el in process:
    local = el.tag.split('}')[-1] if '}' in el.tag else el.tag
    if local in ('startEvent','endEvent','intermediateCatchEvent','intermediateThrowEvent',
                 'task','scriptTask','serviceTask','userTask','sendTask','receiveTask',
                 'businessRuleTask','callActivity','subProcess','boundaryEvent'):
        flow_nodes.append(el.get('id'))

seq_flows = []
for el in process:
    local = el.tag.split('}')[-1] if '}' in el.tag else el.tag
    if local == 'sequenceFlow':
        seq_flows.append(el.get('id'))

print(f"Flow nodes: {flow_nodes}")
print(f"Sequence flows: {seq_flows}")

# Check shapes cover all flow nodes
for nid in flow_nodes:
    if nid not in shape_refs:
        errors.append(f"Flow node {nid} has no BPMNShape")

# Check edges cover all sequence flows
for fid in seq_flows:
    if fid not in edge_refs:
        errors.append(f"SequenceFlow {fid} has no BPMNEdge")

# 3. Check all refs resolve
def check_ref(attr, element, label):
    val = element.get(attr)
    if val and val not in all_ids:
        errors.append(f"{label}: {attr}='{val}' does not resolve to a declared id")

for sf in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow'):
    check_ref('sourceRef', sf, f"sequenceFlow {sf.get('id')}")
    check_ref('targetRef', sf, f"sequenceFlow {sf.get('id')}")

for s in shapes:
    ref = s.get('bpmnElement')
    if ref and ref not in all_ids:
        errors.append(f"BPMNShape bpmnElement='{ref}' does not resolve")

for e in edges:
    ref = e.get('bpmnElement')
    if ref and ref not in all_ids:
        errors.append(f"BPMNEdge bpmnElement='{ref}' does not resolve")

# 4. Check no exclusive gateway issues (none here, skip)

# 5. Check activities/events have at most one incoming flow
incoming_counts = {}
for sf in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow'):
    tgt = sf.get('targetRef')
    incoming_counts[tgt] = incoming_counts.get(tgt, 0) + 1
for nid, cnt in incoming_counts.items():
    if cnt > 1:
        errors.append(f"Node {nid} has {cnt} incoming flows (FAKE_JOIN risk)")

# 6. Check intermediateCatchEvent has uipath:event with type child
for ice in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}intermediateCatchEvent'):
    extelems = ice.find('{http://www.omg.org/spec/BPMN/20100524/MODEL}extensionElements')
    if extelems is None:
        errors.append(f"IntermediateCatchEvent {ice.get('id')} has no extensionElements")
        continue
    evt = extelems.find('{http://uipath.org/schema/bpmn}event')
    if evt is None:
        errors.append(f"IntermediateCatchEvent {ice.get('id')} missing uipath:event")
    else:
        type_el = evt.find('{http://uipath.org/schema/bpmn}type')
        if type_el is None:
            errors.append(f"uipath:event in {ice.get('id')} missing uipath:type child element")
        else:
            print(f"uipath:type value={type_el.get('value')!r} version={type_el.get('version')!r}")
    # Check messageEventDefinition present
    msg_def = ice.find('{http://www.omg.org/spec/BPMN/20100524/MODEL}messageEventDefinition')
    if msg_def is None:
        errors.append(f"IntermediateCatchEvent {ice.get('id')} missing bpmn:messageEventDefinition")
    else:
        print(f"messageEventDefinition present: yes")
    # Check incoming and outgoing
    incoming = ice.findall('{http://www.omg.org/spec/BPMN/20100524/MODEL}incoming')
    outgoing = ice.findall('{http://www.omg.org/spec/BPMN/20100524/MODEL}outgoing')
    print(f"CatchEvent incoming: {[i.text for i in incoming]}, outgoing: {[o.text for o in outgoing]}")

# 7. Check start event is plain (no event definition) - manual start
for se in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}startEvent'):
    has_def = any(
        child.tag.endswith('EventDefinition') or child.tag.endswith('eventDefinition')
        for child in se
        if not child.tag.endswith('extensionElements') and not child.tag.endswith('outgoing') and not child.tag.endswith('incoming')
    )
    print(f"StartEvent {se.get('id')!r} is plain (no event def): {not has_def}")

if errors:
    print("\nERRORS:")
    for e in errors:
        print(f"  - {e}")
else:
    print("\nAll structural checks PASSED")
EOF
